INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='cancellations' WHERE r.slug IN('administrateur','administrateur-systeme');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='cancellations' AND p.action IN('read','create') WHERE r.slug IN('directeur-site','responsable-site','gestionnaire-stock');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='cancellations' AND p.action IN('read','validate','update') WHERE r.slug IN('direction','directeur-general','directeur-financier','auditeur');
